---TEST---
import { test } from "node:test";
import assert from "node:assert/strict";
import { pages, EMPTY } from "../web/list.js";

test("25 orders are three pages of ten", () => {
  const p = pages(Array.from({ length: 25 }, (_, i) => i));
  assert.deepEqual(p.map((x) => x.length), [10, 10, 5]);
});

test("an empty list says so", () => {
  assert.equal(EMPTY, "No hay pedidos");
});
---LIST---
import { readFileSync } from "node:fs";

const config = JSON.parse(readFileSync(new URL("../config/app.json", import.meta.url), "utf8"));

export const EMPTY = "";

export function pages(items) {
  const out = [];
  for (let i = 0; i < items.length; i += config.pageSize) out.push(items.slice(i, i + config.pageSize));
  return out;
}

